Definition P_SR_LOOP1 : Z := 0x378e0.
Definition P_SR_LOOP1_END : Z := 0x378fc.

(* [comment removed for export] *)
Definition sr_skip_post (ra sp gp tp t0 t1 t2 s0 s1 : word) (res lst pos n outend it root sz : Z)
    (s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) : machine_state -> Prop :=
  fun ms' => ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz lst) (wz pos) (wz n) (wz outend) (wz it) (wz root) (wz sz)
                            s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 P_SR_LOOP1_END) fc None m (seg_rom usegs).
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

Lemma sr_skip : forall (R D T : list mbe) (m : mem) (b insz res n outend : Z) (es : list mbe) (ls : LS) (a7v : word)
    (ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  dl_ok (b + 8) (map fst es) ls -> LSCells m ls -> MBElems m es -> mb_addr_ok b es ->
  es = D ++ R ++ T -> R <> [] -> T <> [] ->
  mb_cap (D ++ R) <= insz -> insz < 2^64 -> 0 <= mb_cap D ->
  mem_inv usegs m ->
  evt usegs (sr_skip_post ra sp gp tp t0 t1 t2 s0 s1 res (mb_lasta b es) (insz - mb_cap (D ++ R)) n outend
                (fst (hd (0,0) T)) (b + 8) (mb_lasts R) s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz res) (wz (mb_lasta b es)) (wz (insz - mb_cap D)) (wz n) (wz outend)
               (wz (fst (hd (0,0) R))) (wz (b + 8)) a7v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
